package com.dopaminesimulator;

import com.dopaminesimulator.core.DopamineEvent;
import com.dopaminesimulator.core.DopamineState;
import com.dopaminesimulator.core.RewardQueue;
import com.dopaminesimulator.points.ClickState;
import com.dopaminesimulator.points.GnomeFood;
import com.dopaminesimulator.points.PointSource;
import com.dopaminesimulator.systems.PointSystem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SurgeTest
{
	private static final long NOW = 1_000_000L;

	private DopamineState unlocked()
	{
		DopamineState state = new DopamineState();
		state.ensureInitialised();
		state.setLifetimePoints(10_000_000d);
		return state;
	}

	/** A dish served and eaten, which is the only way one ever does anything. */
	private ClickState serving(GnomeFood food)
	{
		ClickState clicks = plated(food);
		if (food != null)
		{
			clicks.eat(NOW);
		}
		return clicks;
	}

	/** A dish sat in front of the player, not yet clicked. */
	private ClickState plated(GnomeFood food)
	{
		ClickState clicks = new ClickState();
		if (food != null)
		{
			clicks.serve(food, NOW);
		}
		return clicks;
	}

	/** What one event pays with the dish running. */
	private double payout(GnomeFood food, DopamineEvent event)
	{
		ClickState clicks = serving(food);
		DopamineState state = unlocked();
		new PointSystem(null, () -> clicks.incomeMultiplier(NOW))
			.handle(state, event, new RewardQueue());
		return state.getPoints();
	}

	@Test
	public void aWormHoleLiftsEverySourceIncludingClicking()
	{
		// the dish reads "All sources 4x", and clicking is the source a player is
		// actually looking at when they eat one. It used to be the only source the
		// multiplier skipped, so on a fresh profile the 4x showed up nowhere.
		assertEquals("clicking must get the same lift the dish advertises",
			GnomeFood.WORM_HOLE_MULTIPLIER,
			serving(GnomeFood.WORM_HOLE).clickPayoutMultiplier(NOW), 1e-9d);

		for (DopamineEvent event : new DopamineEvent[]{
			DopamineEvent.xp("Attack", 10_000),
			DopamineEvent.kill("Goblin", 50),
			DopamineEvent.loot("Goblin", 100_000),
			DopamineEvent.distance(10),
			DopamineEvent.healthRestored(20),
			DopamineEvent.damageTaken(20),
		})
		{
			double plain = payout(null, event);
			double fed = payout(GnomeFood.WORM_HOLE, event);
			assertEquals(PointSource.forEvent(event.getType()) + " missed the worm hole",
				GnomeFood.WORM_HOLE_MULTIPLIER, fed / plain, 1e-9d);
		}
	}

	@Test
	public void aFrenzyStaysAClickDishAndAWormHoleStaysAnEveryoneDish()
	{
		assertEquals("the frenzy pays clicks and only clicks",
			GnomeFood.FRENZY_MULTIPLIER,
			serving(GnomeFood.SPICY_CRUNCHIES).clickPayoutMultiplier(NOW), 1e-9d);
		assertEquals("and must not touch the other sources", 1d,
			serving(GnomeFood.SPICY_CRUNCHIES).incomeMultiplier(NOW), 1e-9d);
	}

	@Test
	public void noDishDoesAnythingUntilItIsEaten()
	{
		for (GnomeFood food : GnomeFood.values())
		{
			ClickState clicks = plated(food);
			assertEquals(food + " must pay nothing while it sits on the plate", 1d,
				clicks.clickPayoutMultiplier(NOW), 1e-9d);
			assertTrue(food + " must not count as a running surge", !clicks.isSurging(NOW));
			assertTrue(food + " must not have soured anybody", !clicks.isSoured(NOW));
			assertEquals(food + " must be on the plate", food, clicks.getPlated(NOW));
		}
	}

	@Test
	public void aDishLeftAloneForTheWholeWindowIsLost()
	{
		for (GnomeFood food : GnomeFood.values())
		{
			ClickState clicks = plated(food);
			long last = NOW + ClickState.SERVE_WINDOW_MS - 1L;
			assertEquals(food + " must still be eatable at the last moment",
				food, clicks.getPlated(last));

			long after = NOW + ClickState.SERVE_WINDOW_MS;
			assertEquals(food + " must be off the plate", null, clicks.getPlated(after));
			assertEquals("a click after the window eats nothing", null, clicks.eat(after));
			assertTrue("so nothing runs", !clicks.isSurging(after));
			assertTrue("and nothing sours", !clicks.isSoured(after));
			assertEquals(1d, clicks.clickPayoutMultiplier(after), 1e-9d);
		}
	}

	@Test
	public void aDishThatLastsRunsFromTheClickNotFromTheServing()
	{
		ClickState clicks = plated(GnomeFood.WORM_HOLE);
		long ate = NOW + ClickState.SERVE_WINDOW_MS - 1L;
		assertEquals(GnomeFood.WORM_HOLE, clicks.eat(ate));

		long lastMs = ate + GnomeFood.WORM_HOLE.getDurationMs() - 1L;
		assertTrue("it must run its full length from the bite", clicks.isSurging(lastMs));
		assertEquals(GnomeFood.WORM_HOLE_MULTIPLIER,
			clicks.clickPayoutMultiplier(lastMs), 1e-9d);
		assertTrue("and stop there",
			!clicks.isSurging(ate + GnomeFood.WORM_HOLE.getDurationMs()));
	}

	@Test
	public void aWormBattaOnlyCostsThePlayerWhoBitesIt()
	{
		ClickState clicks = plated(GnomeFood.WORM_BATTA);
		assertEquals("the bite is what sours", GnomeFood.WORM_BATTA, clicks.eat(NOW));
		assertEquals("and it halves the click that took it",
			GnomeFood.SOUR_MULTIPLIER, clicks.clickPayoutMultiplier(NOW), 1e-9d);

		long lastSourMs = NOW + GnomeFood.SOUR_MS - 1L;
		assertTrue("the sour runs for the full minute", clicks.isSoured(lastSourMs));
		assertEquals(GnomeFood.SOUR_MULTIPLIER, clicks.incomeMultiplier(lastSourMs), 1e-9d);
		assertTrue("and then lets go", !clicks.isSoured(NOW + GnomeFood.SOUR_MS));
		assertEquals(1d, clicks.clickPayoutMultiplier(NOW + GnomeFood.SOUR_MS), 1e-9d);
	}

	@Test
	public void oneServingCanOnlyBeEatenOnce()
	{
		for (GnomeFood food : GnomeFood.values())
		{
			ClickState clicks = plated(food);
			assertEquals(food, clicks.eat(NOW));

			// A clicker gets clicked. A second click must not eat the same dish
			// again, or a trap would never let a fast clicker go.
			assertEquals(food + " was eaten twice", null, clicks.eat(NOW + 100L));
			assertTrue("the sour still ends a minute after the bite",
				!clicks.isSoured(NOW + GnomeFood.SOUR_MS));
		}
	}

	@Test
	public void aSourHalvesTheDishItIsEatenWith()
	{
		ClickState clicks = plated(GnomeFood.WORM_BATTA);
		clicks.eat(NOW);
		clicks.serve(GnomeFood.WORM_HOLE, NOW);
		clicks.eat(NOW);

		assertEquals("a worm hole eaten while soured pays half what it says",
			GnomeFood.WORM_HOLE_MULTIPLIER * GnomeFood.SOUR_MULTIPLIER,
			clicks.clickPayoutMultiplier(NOW), 1e-9d);
	}

	@Test
	public void theInstantDishesDoNotLeaveAMultiplierRunning()
	{
		for (GnomeFood food : GnomeFood.values())
		{
			// The trap has no duration either, but a sour is exactly the thing it
			// leaves behind. aWormBattaOnlyCostsThePlayerWhoBitesIt covers it.
			if (food.lasts() || food.isTrap())
			{
				continue;
			}
			assertEquals(food + " pays out once, so nothing should linger", 1d,
				serving(food).clickPayoutMultiplier(NOW), 1e-9d);
		}
	}

	@Test
	public void everyDishThatLastsIsWorthSomethingWhileItRuns()
	{
		for (GnomeFood food : GnomeFood.values())
		{
			if (!food.lasts())
			{
				continue;
			}
			assertTrue(food + " runs for " + food.getDurationMs()
					+ "ms and multiplies nothing",
				serving(food).clickPayoutMultiplier(NOW) > 1d
					|| serving(food).incomeMultiplier(NOW) > 1d);
		}
	}
}

package com.dopaminesimulator;

import com.dopaminesimulator.points.ClickState;
import com.dopaminesimulator.points.GnomeFood;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Drives the serving loop the way onGameTick does, over real ClickState and real
 * GnomeFood.roll, so the rate and the spread are measured rather than assumed.
 */
public class FoodSpawnTest
{
	private static final long TICK_MS = 600L;
	private static final int TICKS_PER_HOUR = 6_000;

	/** The guard and roll from DopamineSimulatorPlugin.rollForSurge, tick by tick. */
	private Map<GnomeFood, Integer> run(int hours, int clickLevel, long seed)
	{
		Map<GnomeFood, Integer> served = new EnumMap<>(GnomeFood.class);
		ClickState clicks = new ClickState();
		Random random = new Random(seed);
		long now = 1_000_000L;

		for (int tick = 0; tick < hours * TICKS_PER_HOUR; tick++)
		{
			now += TICK_MS;
			if (clicks.isSurging(now) || clicks.isPlated(now))
			{
				continue;
			}
			if (random.nextDouble() >= ClickState.surgeChancePerTick(clickLevel, 1d))
			{
				continue;
			}
			GnomeFood food = GnomeFood.roll(random);
			clicks.serve(food, now);
			served.merge(food, 1, Integer::sum);
		}
		return served;
	}

	private int total(Map<GnomeFood, Integer> served)
	{
		return served.values().stream().mapToInt(Integer::intValue).sum();
	}

	@Test
	public void dishesAreServedAtTheAdvertisedRate()
	{
		int hours = 2_000;
		int count = total(run(hours, 0, 12345L));
		double perHour = count / (double) hours;
		double advertised = ClickState.surgesPerHour(0);

		System.out.println("level 0: " + String.format("%.2f", perHour) + " dishes/hr"
			+ " (panel says " + String.format("%.2f", advertised) + ")");

		assertTrue("no dishes served at all in " + hours + " hours", count > 0);
		assertEquals("served rate must match what the panel advertises",
			advertised, perHour, advertised * 0.05d);
	}

	/**
	 * The served rate always lands a little under the per-tick chance, because a
	 * dish that is already running skips the roll. The faster the kitchen, the
	 * more of that there is, so the gap widens with the level rather than closing.
	 */
	@Test
	public void aMaxedClickLevelServesMore()
	{
		for (int level : new int[]{0, 10, ClickState.MAX_LEVEL})
		{
			double served = total(run(2_000, level, 999L)) / 2_000d;
			double advertised = ClickState.surgesPerHour(level);
			System.out.println("level " + level + ": " + String.format("%.2f", served)
				+ " dishes/hr served, panel advertises " + String.format("%.2f", advertised)
				+ " (" + String.format("%+.1f%%", 100d * (served - advertised) / advertised) + ")");

			assertTrue("a higher level must not serve fewer", served >= 7d);
			assertTrue("served rate must not exceed the roll chance", served <= advertised * 1.02d);
			assertTrue("and must not fall far under it", served >= advertised * 0.9d);
		}
	}

	@Test
	public void everyDishOnTheMenuGetsServed()
	{
		Map<GnomeFood, Integer> served = run(20_000, 0, 42L);
		int count = total(served);
		System.out.println("over " + count + " dishes:");
		for (GnomeFood food : GnomeFood.values())
		{
			int times = served.getOrDefault(food, 0);
			double share = 100d * times / count;
			System.out.println(String.format("  %-22s %6d  %5.2f%%  (weight says %5.2f%%)",
				food.getDisplayName(), times, share, expectedShare(food)));
			assertTrue(food + " never came out of the kitchen", times > 0);
			assertEquals(food + " is served at the wrong rate",
				expectedShare(food), share, 0.5d);
		}
	}

	private double expectedShare(GnomeFood food)
	{
		int total = 0;
		for (GnomeFood other : GnomeFood.values())
		{
			total += other.getWeight();
		}
		return 100d * food.getWeight() / total;
	}

	@Test
	public void aPlatedDishOnlyHoldsTheKitchenForItsWindow()
	{
		for (GnomeFood food : GnomeFood.values())
		{
			ClickState clicks = new ClickState();
			long now = 1_000_000L;
			clicks.serve(food, now);

			assertTrue(food + ": the guard must hold while it waits",
				clicks.isPlated(now + ClickState.SERVE_WINDOW_MS - 1L));
			assertTrue(food + ": and let go the moment the window shuts",
				!clicks.isPlated(now + ClickState.SERVE_WINDOW_MS));
			assertTrue(food + ": an uneaten dish must leave nothing running",
				!clicks.isSurging(now + ClickState.SERVE_WINDOW_MS));
		}
	}

	@Test
	public void everyDishGetsTheSameTenSecondsToBeClicked()
	{
		assertEquals("the window players were promised", 10_000L, ClickState.SERVE_WINDOW_MS);

		for (GnomeFood food : GnomeFood.values())
		{
			ClickState clicks = new ClickState();
			long now = 1_000_000L;
			clicks.serve(food, now);

			assertEquals(food + " must be on the plate", food, clicks.getShown(now));
			assertEquals(food + " must still be there at the last moment", food,
				clicks.getShown(now + ClickState.SERVE_WINDOW_MS - 1L));
			assertEquals(food + " must be gone after the window", null,
				clicks.getShown(now + ClickState.SERVE_WINDOW_MS));
		}
	}

	/** Eaten, a dish that lasts keeps the plate for as long as it runs. */
	@Test
	public void anEatenDishStaysOnTheButtonWhileItRuns()
	{
		for (GnomeFood food : GnomeFood.values())
		{
			ClickState clicks = new ClickState();
			long now = 1_000_000L;
			clicks.serve(food, now);
			clicks.eat(now);

			if (food.lasts())
			{
				assertEquals(food + " must hold the button while it runs", food,
					clicks.getShown(now + food.getDurationMs() - 1L));
				assertEquals(food + " must clear when it ends", null,
					clicks.getShown(now + food.getDurationMs()));
			}
			else
			{
				assertEquals(food + " pays out at once, so the plate clears", null,
					clicks.getShown(now));
			}
		}
	}
}

package com.dopaminesimulator;

import com.dopaminesimulator.cards.Card;
import com.dopaminesimulator.cards.CardCatalogue;
import com.dopaminesimulator.ui.CardArtService;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.SpriteManager;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Why a big Cards view froze the game.
 *
 * <p>SpriteManager.getSpriteAsync misses its cache and hands ClientThread a
 * BooleanSupplier. ClientThread.invokeList removes a task that returns true and
 * <em>keeps</em> one that returns false, retrying it every tick. The supplier
 * getSpriteAsync builds returns false whenever the sprite does not resolve, so
 * a sprite that never resolves is a task that never leaves the queue.
 *
 * <p>That makes a duplicate request permanent tick cost. This drives the real
 * RuneLite classes and counts what ends up in that queue.
 */
public class SpriteRequestLeakTest
{
	private ClientThread clientThread;
	private SpriteManager spriteManager;
	private CardArtService artService;
	private List<Card> spriteCards;

	@Before
	public void setUp() throws Exception
	{
		// isClientThread() false keeps invoke() on the invokeLater path, so tasks
		// queue instead of running. The queue is exactly what we want to measure.
		Client client = (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[]{Client.class},
			(proxy, method, callArgs) ->
			{
				if ("isClientThread".equals(method.getName()))
				{
					return false;
				}
				Class<?> type = method.getReturnType();
				if (!type.isPrimitive())
				{
					return null;
				}
				return boolean.class.equals(type) ? Boolean.FALSE : 0;
			});

		clientThread = new ClientThread();
		set(clientThread, "client", client);

		Constructor<SpriteManager> ctor = SpriteManager.class.getDeclaredConstructor(
			Client.class, ClientThread.class,
			Class.forName("net.runelite.client.ui.overlay.infobox.InfoBoxManager"));
		ctor.setAccessible(true);
		spriteManager = ctor.newInstance(client, clientThread, null);

		artService = new CardArtService(null, spriteManager);

		spriteCards = new ArrayList<>();
		for (Card card : CardCatalogue.all())
		{
			if (card.getSpriteId() > 0)
			{
				spriteCards.add(card);
			}
		}
		assertTrue("expected sprite backed cards to exist", spriteCards.size() > 100);
	}

	/** The mechanism, straight from SpriteManager: duplicates pile up. */
	@Test
	public void duplicateRequestsAccumulateInTheClientThreadQueue()
	{
		int sprite = spriteCards.get(0).getSpriteId();
		for (int i = 0; i < 50; i++)
		{
			spriteManager.getSpriteAsync(sprite, 0, image ->
			{
			});
		}
		assertEquals("every duplicate request is another task the client thread"
			+ " retries every tick until the sprite resolves", 50, queued());
	}

	/** The fix: one request per card, however many times the panel rebuilds. */
	@Test
	public void rebuildingDoesNotQueueMoreWork()
	{
		int afterFirst = -1;
		for (int rebuild = 1; rebuild <= 20; rebuild++)
		{
			// what a Cards tab rebuild does: every owned card asks to be told
			// when its art lands
			for (Card card : spriteCards)
			{
				artService.onLoaded(card, () ->
				{
				});
			}
			if (rebuild == 1)
			{
				afterFirst = queued();
				System.out.println("after 1 rebuild:   " + afterFirst + " queued tasks");
			}
		}
		System.out.println("after 20 rebuilds: " + queued() + " queued tasks");

		assertTrue("the first rebuild should request the art it needs", afterFirst > 0);
		assertTrue("a card should not be requested twice", afterFirst <= spriteCards.size());
		assertEquals("rebuilding must not add client thread work, or the queue grows"
			+ " without bound and every tick gets slower", afterFirst, queued());
	}

	/** get() must not reopen the hole onLoaded closed. */
	@Test
	public void paintingRepeatedlyDoesNotQueueMoreWork()
	{
		for (Card card : spriteCards)
		{
			artService.onLoaded(card, () ->
			{
			});
		}
		int afterLoad = queued();

		// paints, which call get() for art that has not arrived yet
		for (int paint = 0; paint < 20; paint++)
		{
			for (Card card : spriteCards)
			{
				artService.get(card);
			}
		}
		assertEquals("get() queued more work on every paint", afterLoad, queued());
	}

	private int queued()
	{
		return ((Collection<?>) get(clientThread, "invokes")).size();
	}

	private static void set(Object target, String name, Object value)
	{
		try
		{
			Field field = target.getClass().getDeclaredField(name);
			field.setAccessible(true);
			field.set(target, value);
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalStateException(e);
		}
	}

	private static Object get(Object target, String name)
	{
		try
		{
			Field field = target.getClass().getDeclaredField(name);
			field.setAccessible(true);
			return field.get(target);
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

