package com.dopaminesimulator;

import com.dopaminesimulator.points.ClickState;
import com.dopaminesimulator.points.GnomeFood;
import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

public class SurgeInfoBox extends InfoBox
{
	private static final Color SURGE = new Color(0xFF, 0xE0, 0x82);
	private static final Color SOUR = new Color(0xFF, 0x6B, 0x60);
	private final DopamineSimulatorConfig config;
	private final ClickState clickState;
	SurgeInfoBox(BufferedImage image, Plugin plugin, DopamineSimulatorConfig config,
				 ClickState clickState)
	{
		super(image, plugin);
		this.config = config;
		this.clickState = clickState;
		setTooltip("A gnome dish is being served");
	}
	@Override
	public String getText()
	{
		long now = System.currentTimeMillis();
		GnomeFood plated = clickState.getPlated(now);
		if (plated != null)
		{
			setTooltip(plated.isTrap()
				? plated.getDisplayName() + ": leave it. " + plated.getBlurb()
				: plated.getDisplayName() + ": click to eat it. " + plated.getBlurb());
			return String.format("%.0f", clickState.plateSecondsRemaining(now));
		}

		GnomeFood food = clickState.getActive(now);
		if (food != null)
		{
			setTooltip(food.getDisplayName() + ": " + food.getBlurb());
			return String.format("%.0f", clickState.secondsRemaining(now));
		}
		setTooltip("Soured: every source pays half");
		return String.format("%.0f", clickState.sourSecondsRemaining(now));
	}

	@Override
	public Color getTextColor()
	{
		long now = System.currentTimeMillis();
		GnomeFood plated = clickState.getPlated(now);
		if (plated != null)
		{
			return plated.isTrap() ? SOUR : SURGE;
		}
		return clickState.isSurging(now) ? SURGE : SOUR;
	}

	@Override
	public boolean render()
	{
		long now = System.currentTimeMillis();
		return config.showPackInfobox() && config.gnomeFoodAnnouncements()
			&& (clickState.isPlated(now) || clickState.isSurging(now)
				|| clickState.isSoured(now));
	}
}

