package com.dopaminesimulator.points;

public class ClickRate
{
	public static final double PER_SECOND = 8d;

	public static final double BURST = 10d;

	private double tokens = BURST;
	private long lastMs;

	public boolean take(long nowMs)
	{
		if (lastMs > 0L && nowMs > lastMs)
		{
			tokens = Math.min(BURST, tokens + (nowMs - lastMs) / 1000d * PER_SECOND);
		}
		lastMs = nowMs;
		if (tokens < 1d)
		{
			return false;
		}
		tokens -= 1d;
		return true;
	}

	public double available()
	{
		return tokens;
	}
}

