import java.util.List;
import javax.swing.JComponent;

public class WrappedLabel extends JComponent
{
	private final String text;
	private final Font font;
	private final Color colour;
	private final int wrapWidth;
	private List<String> lines;
	private int lineHeight;
	public WrappedLabel(String text, Font font, Color colour, int wrapWidth)
	{
		this.text = text;
		this.font = font;
		this.colour = colour;
		this.wrapWidth = wrapWidth;

		setOpaque(false);
		layoutText();
	}
	private void layoutText()
	{
		FontMetrics metrics = getFontMetrics(font);
		lineHeight = metrics.getHeight();
		lines = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		for (String word : text.split(" "))
		{
			String candidate = current.length() == 0 ? word : current + " " + word;
			if (metrics.stringWidth(candidate) <= wrapWidth || current.length() == 0)
			{
				current.setLength(0);
				current.append(candidate);
			}
			else
			{
				lines.add(current.toString());
				current.setLength(0);
				current.append(word);
			}
		}

		if (current.length() > 0)
		{
			lines.add(current.toString());
		}
		Dimension size = new Dimension(wrapWidth,
			Math.max(lineHeight, lines.size() * lineHeight) + 2);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
	}
	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		g.setFont(font);
		g.setColor(colour);
		int y = g.getFontMetrics().getAscent();
		for (String line : lines)
		{
			g.drawString(line, 0, y);
			y += lineHeight;
		}
		g.dispose();
	}
}

